function countGoodStrings(low, high, zero, one) {
    const mod = 10 ** 9 + 7;
    const f = new Array(high + 1).fill(0);
    f[0] = 1;
    for (let i = 1; i <= high; i++) {
        if (i >= zero)
            f[i] += f[i - zero];
        if (i >= one)
            f[i] += f[i - one];
        f[i] %= mod;
    }
    const ans = f.slice(low, high + 1).reduce((acc, cur) => acc + cur, 0);
    return ans % mod;
}

